async function createUserProfileAndSettings(params) {
	const existingProfile = await getUserProfile(params.uid);
	if (existingProfile) return {
		profile: existingProfile,
		settings: await ensureUserPrivateSettings(params.uid, params.email)
	};
	const cleanUsername = sanitizeUsername(params.username);
	const usernameLower = cleanUsername.toLowerCase();
	if (cleanUsername.length < 3) throw new Error("Username must be at least 3 characters (letters, numbers, underscores).");
	if (!await checkUsernameAvailable(cleanUsername)) throw new Error(`Username @${cleanUsername} is already taken. Please choose another.`);
	const defaultCover = (params.coverUrl || "").slice(0, 25e4);
	const batch = writeBatch(db);
	const userRef = doc(db, "users", params.uid);
	const settingsRef = doc(db, "users", params.uid, "private", "settings");
	const usernameRef = doc(db, "usernames", usernameLower);
	const profilePayload = {
		uid: params.uid,
		username: cleanUsername,
		usernameLower,
		fullName: params.fullName.trim().slice(0, 64) || cleanUsername,
		bio: "",
		hostel: (params.hostel || "").trim().slice(0, 80),
		avatarUrl: (params.avatarUrl || "").slice(0, 32768),
		coverUrl: defaultCover,
		followersCount: 0,
		followingCount: 0,
		postsCount: 0,
		isSuspended: false,
		createdAt: serverTimestamp(),
		updatedAt: serverTimestamp()
	};
	const settingsPayload = {
		uid: params.uid,
		email: params.email.slice(0, 254),
		privacyMode: "public",
		notifyLikes: true,
		notifyComments: true,
		notifyFollows: true,
		notifyMessages: true,
		blockedUserIds: [],
		updatedAt: serverTimestamp()
	};
	batch.set(userRef, profilePayload);
	batch.set(settingsRef, settingsPayload);
	batch.set(usernameRef, {
		uid: params.uid,
		createdAt: serverTimestamp()
	});
	try {
		await batch.commit();
	} catch (error) {
		handleFirestoreError(error, OperationType.WRITE, `users/${params.uid}`);
	}
	const [createdProfile, createdSettings] = await Promise.all([getUserProfile(params.uid), getUserPrivateSettings(params.uid)]);
	if (!createdProfile || !createdSettings) throw new Error("Profile created but could not be loaded. Please refresh.");
	return {
		profile: createdProfile,
		settings: createdSettings
	};
}
async function updateUserProfile(uid, currentUsernameLower, updates) {
	const userRef = doc(db, "users", uid);
	const batch = writeBatch(db);
	const payload = { updatedAt: serverTimestamp() };
	if (typeof updates.fullName === "string") {
		const trimmed = updates.fullName.trim().slice(0, 64);
		if (!trimmed) throw new Error("Full name cannot be empty.");
		payload.fullName = trimmed;
	}
	if (typeof updates.bio === "string") payload.bio = updates.bio.trim().slice(0, 240);
	if (typeof updates.hostel === "string") payload.hostel = updates.hostel.trim().slice(0, 80);
	if (typeof updates.avatarUrl === "string") payload.avatarUrl = updates.avatarUrl.slice(0, 32768);
	if (typeof updates.coverUrl === "string") payload.coverUrl = updates.coverUrl.slice(0, 25e4);
	if (typeof updates.username === "string") {
		const clean = sanitizeUsername(updates.username);
		const nextLower = clean.toLowerCase();
		if (clean.length < 3) throw new Error("Username must be at least 3 characters.");
		if (nextLower !== currentUsernameLower) {
			if (!await checkUsernameAvailable(clean)) throw new Error(`Username @${clean} is already reserved.`);
			batch.delete(doc(db, "usernames", currentUsernameLower));
			batch.set(doc(db, "usernames", nextLower), {
				uid,
				createdAt: serverTimestamp()
			});
			payload.username = clean;
			payload.usernameLower = nextLower;
		}
	}
	batch.update(userRef, payload);
	try {
		await batch.commit();
	} catch (error) {
		handleFirestoreError(error, OperationType.UPDATE, `users/${uid}`);
	}
	const refreshed = await getUserProfile(uid);
	if (!refreshed) throw new Error("Unable to refresh updated profile.");
	return refreshed;
}
