async function toggleLikeStory(story, actor, currentlyLiked) {
	const likeId = `${story.id}_${actor.uid}`;
	const likeRef = doc(db, "storyLikes", likeId);
	const storyRef = doc(db, "stories", story.id);
	const batch = writeBatch(db);
	if (currentlyLiked) {
		batch.delete(likeRef);
		batch.update(storyRef, { likesCount: increment(-1) });
	} else {
		batch.set(likeRef, {
			id: likeId,
			storyId: story.id,
			storyAuthorId: story.authorId,
			userId: actor.uid,
			userUsername: actor.username,
			userName: actor.fullName,
			userAvatarUrl: (actor.avatarUrl || "").slice(0, 32768),
			createdAt: serverTimestamp()
		});
		batch.update(storyRef, { likesCount: increment(1) });
	}
	try {
		await batch.commit();
	} catch (error) {
		handleFirestoreError(error, OperationType.WRITE, `storyLikes/${likeId}`);
	}
}
